import { ProtocolStateMachine, FramingGrammar } from '../domain/types.js';

export function generateGhostNodeScript(stateMachine: ProtocolStateMachine, grammar: FramingGrammar): string {
  return `// ============================================================================
// Auto-generated by PEA (Protocol Engineering Anything)
// Autonomous Distributed Ghost-Node Peer
// Target: ${stateMachine.protocolName}
// ============================================================================

import net from 'node:net';

const MAGIC = ${grammar.magicBytes ? '0x' + grammar.magicBytes.toString(16) : 'null'};
const TARGET_HOST = process.env.PEER_HOST || '127.0.0.1';
const TARGET_PORT = parseInt(process.env.PEER_PORT || '9000', 10);

class GhostNode {
  constructor() {
    this.state = '${stateMachine.initialState}';
    this.socket = new net.Socket();
  }

  connect() {
    console.log(\`[PEA Ghost Node] Connecting to cluster at \${TARGET_HOST}:\${TARGET_PORT}...\`);
    this.socket.connect(TARGET_PORT, TARGET_HOST, () => {
      console.log('[PEA Ghost Node] TCP transport established.');
      this.sendHandshake();
    });

    this.socket.on('data', (buf) => this.handleData(buf));
    this.socket.on('close', () => console.log('[PEA Ghost Node] Connection closed.'));
    this.socket.on('error', (err) => console.error('[PEA Ghost Node] Error:', err.message));
  }

  buildFrame(opcode, payload = Buffer.alloc(0)) {
    const header = Buffer.alloc(${grammar.headerSizeBytes});
    ${grammar.magicBytes ? `header.writeUInt16BE(${grammar.magicBytes}, 0);` : ''}
    header.writeUInt16BE(payload.length, ${grammar.lengthFieldOffset});
    header.writeUInt16BE(opcode, ${grammar.opcodeFieldOffset});
    return Buffer.concat([header, payload]);
  }

  sendHandshake() {
    console.log('[PEA Ghost Node] Dispatching OP_HANDSHAKE_INIT...');
    const frame = this.buildFrame(0x0001);
    this.socket.write(frame);
    this.state = 'HANDSHAKING';
  }

  handleData(buffer) {
    if (buffer.length < ${grammar.headerSizeBytes}) return;

    const opcode = buffer.readUInt16BE(${grammar.opcodeFieldOffset});
    const len = buffer.readUInt16BE(${grammar.lengthFieldOffset});
    console.log(\`[PEA Ghost Node] Received Opcode: 0x\${opcode.toString(16)} (Length: \${len} bytes)\`);

    if (opcode === 0x0002 && this.state === 'HANDSHAKING') {
      console.log('[PEA Ghost Node] Handshake acknowledged. Transitioning to AUTHENTICATING.');
      this.state = 'AUTHENTICATING';
      this.socket.write(this.buildFrame(0x0010)); // OP_AUTH_REQUEST
    } else if (opcode === 0x0011 && this.state === 'AUTHENTICATING') {
      console.log('[PEA Ghost Node] Authenticated! State: ESTABLISHED.');
      this.state = 'ESTABLISHED';
      // Start heartbeat loop
      setInterval(() => {
        this.socket.write(this.buildFrame(0x00FF));
      }, 5000);
    }
  }
}

const node = new GhostNode();
node.connect();
`;
}
